/**
 * Industry briefs for the video prompt library.
 *
 * These are request blueprints, not claims that the poster was generated by
 * the model on the page.  The reference clips are deliberately object- and
 * environment-led so the gallery never quietly turns into a people/UGC
 * showcase.  A visitor can replace the bracketed values and send the brief
 * from the single playground example above.
 */
export type VideoPromptTemplate = {
  id: string;
  label: string;
  prompt: string;
  ratio: string;
  duration: number;
  poster: string;
  /** A playable reference clip; templates never claim it was generated by the page model. */
  video: string;
  tags: readonly string[];
};

