// The brief stays industry-led, while this short model note makes the copy
// useful on the page where it appears: the same product shot can ask for
// continuity, speed, natural light, or compact motion depending on the model.
// Keeping the note in the prompt also means copying a card preserves the
// model-specific intent instead of silently collapsing every page to one
// generic sentence.
const VIDEO_MODEL_PROMPT_NOTES: Record<string, string> = {
  "seedance-2-5": "Favor multi-shot continuity and a clean, editable ending so the clip can be extended without changing the subject.",
  "seedance-2-0": "Favor a single readable take with stable subject identity and a deliberate camera path.",
  "seedance-2-0-pro": "Favor layered depth, precise material response, and controlled transitions between the key beats.",
  "seedance-2-0-fast": "Favor an efficient one-take motion path with an immediate hook and no ornamental camera drift.",
  "seedance-2-0-mini": "Favor a simple subject, uncluttered staging, and high-contrast motion that remains legible at small sizes.",
  "minimax-h3": "Favor natural ambient timing, clear contact shadows, and a stable composition that can be rendered at multiple durations.",
  "grok-imagine-video": "Favor expressive but physically coherent motion, with one controlled visual surprise near the midpoint.",
  "grok-imagine-video-1-5": "Favor polished surface detail, decisive camera movement, and a strong final hero frame for campaign cutdowns.",
  "veo-3-1-generate-preview": "Favor naturalistic light changes, believable environmental motion, and a calm cinematic pace.",
  "veo-3-1-fast-generate-preview": "Favor compact transitions, clear silhouettes, and a production-ready result in the shortest readable beat.",
};

export const VIDEO_MODEL_IDS = Object.freeze(Object.keys(VIDEO_MODEL_POSTER_SETS));

export function getVideoPromptTemplateFallbackPosters(modelId: string): readonly string[] {
  const slug = modelId
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
  return VIDEO_MODEL_POSTER_SETS[slug] ?? [];
}

/** Return six industry templates only for pages with a dedicated video set. */
export function getVideoPromptTemplates(modelId: string): readonly VideoPromptTemplate[] {
  const slug = modelId
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
  const posters = getVideoPromptTemplateFallbackPosters(modelId);
  const videos = VIDEO_MODEL_VIDEO_SETS[slug];
  const note = VIDEO_MODEL_PROMPT_NOTES[slug];
  if (posters.length !== VIDEO_PROMPT_TEMPLATES.length || videos?.length !== VIDEO_PROMPT_TEMPLATES.length || !note) return [];
  return VIDEO_PROMPT_TEMPLATES.map((template, index) => ({
    ...template,
    poster: posters[index],
    video: videos[index],
    prompt: `${template.prompt} ${note}`,
  }));
}
